head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil00044";
scwin.formObj = undefined;
scwin.rtnVal = "";
scwin.chkArrNo = undefined;
scwin.chkTitle = undefined;
scwin.obj = undefined;
scwin.frameId = undefined;
scwin.frame = undefined;

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — langTpCd

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "iframe_9", attr: "src", fn: function () { return "/submission/searchDisclosureDocument.do?method=srchSubmitDoc4VoterghtExerRelDiscls&tgtIsurCd=" + String(String((dma_pageContext.get("tgtIsurCd") ?? ""))) + "&langTpCd=" + String(String((dma_pageContext.get("langTpCd") ?? ""))); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        const v = a.fn();
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_langTpCd", fn: function(){ return ((dma_pageContext.get("langTpCd") ?? "") === '1'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        const ok = !!b.fn();
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.chkArrNo =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil00044' }); }

try { scwin.chkTitle =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil00044' }); }

try { scwin.obj =opener.Potential.Provider; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil00044' }); }

try { scwin.frameId =scwin.obj.ActiveFrame.FrameID; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil00044' }); }

try { scwin.frame =scwin.obj.Provider(scwin.frameId).ActiveFrame; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil00044' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_attrReals();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil00044.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ipt_nonSelect_onclick
 * @description 「-|-」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_nonSelect_onclick = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.noSelected(selfVar)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00044.ipt_nonSelect_onclick' }); }
};

/**
 * @method
 * @name btn_selected_onclick
 * @description btn_selected 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_selected_onclick = async function(e){
    try {
        await scwin.selected()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil00044.btn_selected_onclick' }); }
};

/**
 * @method
 * @name btn_close_onclick
 * @description btn_close 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_close_onclick = function(e){
    try {
        scwin.close()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00044.btn_close_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name checkIt
 * @description check It 처리
 * @param {*} ver ver
 * @returns {void}
 * @hidden N
 */
scwin.checkIt = function (ver) {
    scwin.formObj = (document.form || { elements: [] });
    const subObj = document.iframe.searchForm.relDiscl;
    const nonSelectObj = $c.util.getComponent('ipt_nonSelect');
    let tmpVal = null;
    let arrLength = 0;
    const arrNo = ((ver.value).split("|"))[0];
    scwin.resetRtnVal(arrNo);
    if ((String(nonSelectObj.getValue() || "") !== "") === true) {
        scwin.chkArrNo = [];
        scwin.chkTitle = [];
        nonSelectObj.checked = false;
    }
    if (scwin.chkArrNo.length !== 0) {
        arrLength = scwin.chkArrNo.length;
    }
    if (ver.checked === true) {
        tmpVal = (ver.value).split("|");
        scwin.chkArrNo[arrLength] = tmpVal[0];
        scwin.chkTitle[arrLength] = tmpVal[1];
    }
    scwin.rtnVal = scwin.chkArrNo.join(",") + "|" + scwin.chkArrNo.join("\n");
    (($c.util.getComponent("txt_docs")) && ($c.util.getComponent("txt_docs")).setValue ? ($c.util.getComponent("txt_docs")).setValue(scwin.chkTitle.join("<br/>")) : (($c.util.getComponent("txt_docs")) ? (($c.util.getComponent("txt_docs")).innerHTML = scwin.chkTitle.join("<br/>")) : void (scwin.chkTitle.join("<br/>"))));
};

/**
 * @method
 * @name resetRtnVal
 * @description reset Rtn Val 처리
 * @param {*} ver ver
 * @returns {void}
 * @hidden N
 */
scwin.resetRtnVal = function (ver) {
    const tmpArr1 = [];
    const tmpArr2 = [];
    let cnt = 0;
    for (let i = 0; i < scwin.chkArrNo.length; i++) {
        if (scwin.chkArrNo[i] !== ver) {
            tmpArr1[cnt] = scwin.chkArrNo[i];
            tmpArr2[cnt] = scwin.chkTitle[i];
            cnt++;
        }
    }
    scwin.chkArrNo = [];
    scwin.chkTitle = [];
    scwin.chkArrNo = tmpArr1;
    scwin.chkTitle = tmpArr2;
};

/**
 * @method
 * @name selected
 * @description selected 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.selected = async function () {
    const chkObj = (document.formCheck || { elements: [] });
    let isChoice = false;
    const subObj = document.iframe.searchForm.relDiscl;
    if (scwin.chkArrNo.length !== 0) {
        isChoice = true;
    }
    if (((String($c.util.getComponent('ipt_nonSelect').getValue() || "") !== "")) || isChoice) {
        scwin.frame.fn_setSelectedData('' + dma_pageContext.get("formKey") + '', '' + dma_pageContext.get("formKey") + '', decodeURIComponent('' + dma_pageContext.get("returnKey") + ''), scwin.chkArrNo.join(","), scwin.chkTitle.join("\n"));
        $c.win.closePopup();
    } else {
        await $c.win.alert("해당사항이 없는 경우 '해당없음'을 체크 하십시오!");
    }
};

/**
 * @method
 * @name noSelected
 * @description no Selected 처리
 * @param {*} ver ver
 * @returns {void}
 * @hidden N
 */
scwin.noSelected = function (ver) {
    scwin.formObj = (document.form || { elements: [] });
    const subObj = document.iframe.searchForm.relDiscl;
    if (ver.checked === true) {
        if (subObj.value !== '') {
            for (let i = 0; i < subObj.relDiscl.length; i++) {
                subObj.relDiscl[i].checked = false;
            }
        }
        $c.util.getComponent('txt_docs').setLabel("");
        scwin.chkArrNo = [];
        scwin.chkTitle = [];
        scwin.chkArrNo[0] = '-';
        scwin.chkTitle[0] = '-';
    } else {
        scwin.chkArrNo = [];
        scwin.chkTitle = [];
    }
};

/**
 * @method
 * @name setCheckedCheckBox
 * @description set Checked Check Box 처리
 * @param {*} ver ver
 * @returns {void}
 * @hidden N
 */
scwin.setCheckedCheckBox = function (ver) {
    const subObj = document.iframe.searchForm.relDiscl;
    let tmpVal = null;
    if (ver !== 0) {
        if (scwin.chkArrNo.length !== 0) {
            for (let i = 0; i < scwin.chkArrNo.length; i++) {
                for (let k = 0; k < subObj.relDiscl.length; k++) {
                    tmpVal = (subObj.relDiscl[k].value).split("|");
                    if (scwin.chkArrNo[i] === tmpVal[0]) {
                        subObj.relDiscl[k].checked = true;
                    }
                }
            }
        }
    }
};

/**
 * @method
 * @name disclsviewer
 * @description disclsviewer 처리
 * @param {*} _acptno _acptno
 * @returns {void}
 * @hidden N
 */
scwin.disclsviewer = function (_acptno) {
    scwin.frame.fn_Disclsviewer(_acptno);
};

/**
 * @method
 * @name close
 * @description close 처리
 * @returns {void}
 * @hidden N
 */
scwin.close = function () {
    $c.win.closePopup();
};
